BD("js/effekt_builtins.js",'$effekt.show \x3d function(obj) {\n  if (!!obj \x26\x26 !!obj.__reflect) {\n    const meta \x3d obj.__reflect()\n    return meta.__name + "(" + meta.__data.map($effekt.show).join(", ") + ")"\n  }\n  else if (!!obj \x26\x26 obj.__unit) {\n    return "()";\n  } else {\n    return "" + obj;\n  }\n}\n\n$effekt.equals \x3d function(obj1, obj2) {\n  if (!!obj1.__equals) {\n    return obj1.__equals(obj2)\n  } else {\n    return (obj1.__unit \x26\x26 obj2.__unit) || (obj1 \x3d\x3d\x3d obj2);\n  }\n}\n\nfunction compare$prim(n1, n2) {\n  if (n1 \x3d\x3d n2) { return 0; }\n  else if (n1 \x3e n2) { return 1; }\n  else { return -1; }\n}\n\n$effekt.compare \x3d function(obj1, obj2) {\n  if ($effekt.equals(obj1, obj2)) { return 0; }\n\n  if (!!obj1 \x26\x26 !!obj2) {\n    if (!!obj1.__reflect \x26\x26 !!obj2.__reflect) {\n      const tagOrdering \x3d compare$prim(obj1.__tag, obj2.__tag)\n      if (tagOrdering !\x3d 0) { return tagOrdering; }\n\n      const meta1 \x3d obj1.__reflect().__data\n      const meta2 \x3d obj2.__reflect().__data\n\n      const lengthOrdering \x3d compare$prim(meta1.length, meta2.length)\n      if (lengthOrdering !\x3d 0) { return lengthOrdering; }\n\n      for (let i \x3d 0; i \x3c meta1.length; i++) {\n        const contentOrdering \x3d $effekt.compare(meta1[i], meta2[i])\n        if (contentOrdering !\x3d 0) { return contentOrdering; }\n      }\n\n      return 0;\n    }\n  }\n\n  return compare$prim(obj1, obj2);\n}\n\n$effekt.println \x3d function println$impl(str) {\n  console.log(str); return $effekt.unit;\n}\n\n$effekt.print \x3d function println$impl(str) {\n  process.stdout.write(str); return $effekt.unit;\n}\n\n$effekt.unit \x3d { __unit: true }\n\n$effekt.unreachable \x3d function() { throw "should not be reachable!" }\n\n$effekt.hole \x3d function(pos) { throw pos + " not implemented yet" }\n');
